import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * JUnit 5 test suite for {@link CycleDetector}.
 *
 * <p>Compile and run with {@code ./run-tests.sh} (no build tool required).
 */
@DisplayName("CycleDetector")
